const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icons={grid:'<rect x="3" y="3" width="7" height="10" rx="1"/><rect x="14" y="3" width="7" height="6" rx="1"/><rect x="3" y="17" width="7" height="4" rx="1"/><rect x="14" y="13" width="7" height="8" rx="1"/>',canvas:'<rect x="5" y="5" width="14" height="14" rx="1" transform="rotate(-10 12 12)"/><path d="m8 15 3-4 3 2 2-2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',check:'<path d="m5 12 4 4L19 6"/>',comment:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7A8.4 8.4 0 0 1 4 11.5 8.5 8.5 0 0 1 8.7 3.9a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',library:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="m4 15 5-5 4 4 3-3 4 4"/><circle cx="15" cy="8" r="1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v9h14v-9"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20.5 13a9 9 0 0 1-9.5-9.5A9 9 0 1 0 20.5 13Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',note:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8m-8 4h6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',archive:'<path d="M4 7h16v14H4zM3 3h18v4H3zM10 11h4"/>',text:'<path d="M4 4h16M12 4v16M8 20h8"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="14" cy="7" r="1"/><circle cx="17" cy="12" r="1"/><path d="M6 17c3-4 7 5 8 2"/>',link:'<path d="m10 13 4-4m-5 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 6a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2" transform="translate(1 2) scale(.85)"/>',undo:'<path d="M3 10h11a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5"/>',redo:'<path d="M21 10H10a6 6 0 0 0 0 12m17-12-5-5m5 5-5 5"/>',hand:'<path d="M8 13V5a2 2 0 0 1 4 0v7-9a2 2 0 0 1 4 0v9-6a2 2 0 0 1 4 0v9c0 6-3 7-7 7-3 0-5-2-6-4l-4-6a2 2 0 0 1 3-2l2 3Z"/>',cursor:'<path d="m4 3 6 18 3-7 7-3L4 3Z"/>',minus:'<path d="M5 12h14"/>',fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',layers:'<path d="m12 3 10 5-10 5L2 8zm-9 10 9 5 9-5M3 18l9 5 9-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',day:'<path d="M3 20h18M12 2v3M4 7l2 2m14-2-2 2M2 14h3m14 0h3"/><path d="M6 17a6 6 0 0 1 12 0"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 3H3v18h6m6-14 5 5-5 5M8 12h12"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7l-5-5L3 15z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const btn=(n,label,cls='btn',attrs='')=>`<button class="${cls}" ${attrs}>${n?icon(n):''}${label?`<span>${label}</span>`:''}</button>`;
const photographyLogo=()=>`<img class="photography-logo logo-dark" src="/logoDark.webp" alt="Mario Romay Photography" width="720" height="720"><img class="photography-logo logo-light" src="/logoLight.webp" alt="Mario Romay Photography" width="720" height="720">`;
const brand=()=>`${photographyLogo()}<span class="brand-title">shoots<span style="color:var(--accent)">.</span></span>`;
const guestToken=location.pathname.match(/^\/g\/([a-f0-9]{64})/)?.[1];
if(guestToken)$('#preview-entry')?.remove();
const base=guestToken?'/api/g/'+guestToken:'/api';
const media=(id,thumb=false)=>`${guestToken?'/media/g/'+guestToken:'/media'}/${encodeURIComponent(id)}${thumb?'?thumb=1':''}`;
let state={me:null,sessions:[],session:null,screen:'sessions',tab:'moodboard',view:'masonry',filter:'all',search:'',sort:'newest',assets:[],archive:false,librarySearch:'',busy:0};
let saveFailure=false;
let dirty=false, pending=Promise.resolve(),lastFocus=null,toastTimer,ro,modalCleanup=null,uploading=false;
let selected=new Set(),canvas={zoom:.7,x:40,y:55,pan:false,snap:true},drag=null,undoStack=[],redoStack=[];
document.documentElement.dataset.theme=localStorage.getItem('shoots-theme')||'dark';
function toast(message,error=false){const e=$('#toast');e.textContent=message;e.style.background=error?'#f0b7a8':'';e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),error?8000:3500)}
function saveStatus(text='All changes saved',error=false){const e=$('#save-status');if(e)e.innerHTML=`<span class="dot" style="${error?'background:#e4a58f':''}"></span>${esc(text)}`}
async function api(path,options={}){const res=await fetch(base+path,{...options,headers:{'X-Shoots-Request':'1',...(!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers},body:options.body instanceof FormData?options.body:options.body===undefined?undefined:JSON.stringify(options.body)});const d=await res.json();if(!res.ok){const e=Object.assign(new Error(d.error||'Request failed'),{status:res.status});if(res.status===401&&state.me&&path!=='/account/password'){state.me=null;login(d.error)}throw e}return d}
function mutate(task){state.busy++;saveFailure=false;saveStatus('Saving…');const job=pending.then(task);pending=job.catch(()=>{});return job.catch(e=>{saveFailure=true;saveStatus(e.status===409?'Conflict · draft kept':'Could not save',true);toast(e.message,true);throw e}).finally(()=>{state.busy--;if(!state.busy&&!saveFailure)saveStatus()})}
function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function dateText(d,short=false){if(!d)return 'Date to be decided';return new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:short?'short':'long',day:'numeric',...(!short?{year:'numeric'}:{})})}
function timeText(t){if(!t)return '';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
const own=()=>state.me?.role==='owner',contribute=()=>state.me?.role!=='view',edit=()=>['owner','collaborate'].includes(state.me?.role);
function modal(html,cls=''){closeModal();lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${cls}" tabindex="-1">${html}</section></div>`;$('.modal').focus();$('.modal-backdrop').addEventListener('pointerdown',e=>{if(e.target===$('.modal-backdrop'))closeModal()});$$('[data-close]').forEach(e=>e.onclick=closeModal);const first=$('input:not([type=hidden]),textarea,button', $('.modal'));first?.focus()}
function modalHead(title){return `<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${btn('close','','icon-btn','data-close aria-label="Close dialog"')}</div>`}
function closeModal(){modalCleanup?.();modalCleanup=null;$('#modal-root').innerHTML='';lastFocus?.focus?.();lastFocus=null}
document.addEventListener('keydown',e=>{if($('.modal')){if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=$$('button,a[href],input,textarea,select,[tabindex="0"]',$('.modal')).filter(el=>!el.disabled&&el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key===' '&&state.view==='canvas'){e.preventDefault();canvas.pan=true;$('.canvas-viewport')?.classList.add('panning')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&state.view==='canvas'){e.preventDefault();historyMove(e.shiftKey)}if(state.view==='canvas'&&selected.size&&edit()&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const delta=e.shiftKey?20:2;const changes=[...selected].map(id=>{const i=findItem(id);return {i,before:structuredClone(i.transform),after:{...i.transform,x:i.transform.x+ (e.key==='ArrowLeft'?-delta:e.key==='ArrowRight'?delta:0),y:i.transform.y+(e.key==='ArrowUp'?-delta:e.key==='ArrowDown'?delta:0)}}});applyChanges(changes)}if(e.key==='Escape'){selected.clear();renderCanvas()}});
document.addEventListener('keyup',e=>{if(e.key===' '){canvas.pan=false;$('.canvas-viewport')?.classList.remove('panning')}});
window.addEventListener('beforeunload',e=>{if(dirty||state.busy){e.preventDefault();e.returnValue=''}});
async function boot(){if(new URLSearchParams(location.search).has('setup')){ownerSetup();return}try{state.me=await api('/me');if(guestToken){await openSession(state.me.session)}else{state.sessions=await api('/sessions');const slug=location.pathname.match(/^\/([a-z0-9-]+)\/?$/)?.[1];const id=slug&&!['admin','client'].includes(slug)?(await api('/shoot-url/'+slug)).id:location.hash.match(/^#session\/([^/]+)/)?.[1];if(id)await openSession(id);else render()}}catch(e){login(e.status===401?'':e.message)}}
function legacyLogin(message=''){ro?.disconnect();$('#app').innerHTML=`<div class="login"><div class="login-visual"><div class="login-quote">Good photographs<br>begin with an idea.</div></div><div class="login-content"><form class="login-form" id="login-form"><a class="brand" href="/">${brand()}</a><div class="eyebrow">${guestToken?'You’re invited':'Your creative workspace'}</div><h1 style="margin-top:13px">${guestToken?'Let’s make something.':'Welcome back, Mario.'}</h1><p>${guestToken?'Gather inspiration, share ideas, and find a direction together. Enter your name to join the session.':'A quiet space for the ideas, conversations, and plans behind your next shoot.'}</p>${guestToken?'<div class="field"><label for="display-name">Your name</label><input id="display-name" name="name" required maxlength="60" autocomplete="name" placeholder="How should we call you?"></div>':''}<div class="field" style="margin-top:17px"><label for="password">${guestToken?'Session PIN, if provided':'Workspace password'}</label><input id="password" name="password" type="password" ${guestToken?'':'required'} autocomplete="current-password" placeholder="${guestToken?'Leave blank if no PIN is set':'Enter your password'}"></div><div class="error" id="login-error">${esc(message)}</div>${btn('arrow',guestToken?'Join session':'Open workspace','btn primary','type="submit"')}<p class="login-note">${icon('lock')} ${guestToken?'No account needed. Your invitation controls access.':'Private photography workspace'}</p></form></div></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{await api('/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});await boot()}catch(err){$('#login-error').textContent=err.message}finally{button.disabled=false}}}
function sidebar(){const s=state;return `<aside class="sidebar"><button class="brand" data-screen="sessions">${brand()}</button><div class="brand-sub">Shoot planning</div>${own()?`<nav aria-label="Main navigation">${btn('grid','Shoots','nav-btn '+((s.screen==='sessions'&&!s.archive)||s.screen==='session'?'active':''),'data-screen="sessions"')} ${btn('library','Inspiration library','nav-btn '+(s.screen==='library'?'active':''),'data-screen="library"')} ${btn('','Clients','nav-btn','id="clients-nav"')} ${btn('archive','Archived shoots','nav-btn '+(s.screen==='sessions'&&s.archive?'active':''),'data-archive-nav')}</nav><div class="side-label">On the drawing board</div>${s.sessions.filter(x=>!x.archived).slice(0,4).map(x=>`<button class="session-nav ${s.session?.id===x.id&&s.screen==='session'?'active':''}" data-session="${x.id}"><span class="dot"></span>${esc(x.details.name.split(' · ')[0])}</button>`).join('')}`:`${state.me?.client?btn('grid','Your shoots','nav-btn','data-screen="sessions"')+btn('lock','Account','nav-btn','id="client-account"'):''}<div class="side-label">Your shoot</div><span class="session-nav active">${esc(s.session?.details.name||'Your shared shoots')}</span>`}<div class="side-bottom"><div class="row muted tiny" style="padding:0 11px">${icon('lock')} A private place to create.</div><div class="owner"><span class="avatar">${esc((s.me?.name||'M').slice(0,1))}</span><div><div class="owner-name">${esc(s.me?.name)}</div><div class="owner-role">${own()?'Photographer':roleText(s.me?.role)}</div></div>${!guestToken?btn('logout','','icon-btn','id="logout" aria-label="Sign out"'):''}</div></div></aside>`}
function roleText(r){return {view:'View only',contribute:'Contributor',collaborate:'Collaborator',owner:'Photographer'}[r]||r}
function render(){ro?.disconnect();const title=state.screen==='session'?state.session?.details.name:state.screen==='library'?'Inspiration library':'Shoots';$('#app').innerHTML=`<div class="shell">${sidebar()}<main><header class="topbar"><button class="icon-btn mobile-menu" id="mobile-menu" aria-label="Open navigation">${icon('menu')}</button><span class="mobile-brand">${photographyLogo()}<span>shoots.</span></span><div class="crumbs"><button data-screen="sessions">Workspace</button>${icon('chevron')}<span>${esc(title)}</span></div><div class="row">${document.body.dataset.preview?'<span class="preview-tag">Sample preview</span>':''}<span class="save" id="save-status"><span class="dot"></span>All changes saved</span>${btn('sun','','icon-btn','id="theme" aria-label="Toggle light or dark theme"')}</div></header><div class="content" id="content">${state.screen==='session'?sessionHTML():state.screen==='library'?libraryHTML():dashboardHTML()}</div></main></div>`;bindGlobal();if(state.screen==='sessions')bindDashboard();if(state.screen==='session')bindSession();if(state.screen==='library')bindLibrary();layoutMasonry();if(state.screen==='session'&&state.tab==='moodboard'&&state.view==='canvas')renderCanvas();bindDrop();}
function bindGlobal(){if($('#clients-nav'))$('#clients-nav').onclick=()=>manageClients();if($('#client-account'))$('#client-account').onclick=changeClientPassword;$$('[data-archive-nav]').forEach(b=>b.onclick=async()=>{state.archive=true;await navigate('sessions')});$$('[data-screen]').forEach(el=>el.onclick=()=>{if(el.dataset.screen==='sessions')state.archive=false;return navigate(el.dataset.screen)});$$('[data-session]').forEach(el=>el.onclick=()=>openSession(el.dataset.session));$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('shoots-theme',document.documentElement.dataset.theme)};$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('mobile-open');if($('#logout'))$('#logout').onclick=async()=>{if(!await flushDrafts())return;await api('/logout',{method:'POST',body:{}});state.me=null;history.replaceState(null,'','/');login()}}
async function flushDrafts(){if(dirty){toast('Save your current edits before leaving this view.',true);return false}await pending;return true}
async function navigate(screen){if(!own()&&!state.me?.client)return;if(state.me?.client&&screen!=='sessions')return;if(!await flushDrafts())return;state.screen=screen;state.session=null;state.search='';history.replaceState(null,'','/');if(screen==='library')state.assets=await api('/library');else state.sessions=await api('/sessions');render()}
function dashboardHTML(){const items=state.sessions.filter(s=>!!s.archived===state.archive);return `<div class="dashboard-hero"><div><div class="eyebrow">A space for what’s next</div><h1>The plan behind<br>the photographs.</h1><p>Gather inspiration. Find a direction. Make something together.</p></div>${own()?btn('plus','New shoot','btn primary','id="new-session"'):''}</div><div class="section-bar"><h2>${state.archive?'Archived shoots':'Your shoots'} <span class="muted tiny" style="margin-left:6px">${items.length}</span></h2><div class="filters"><button class="filter ${!state.archive?'active':''}" data-archive="false">Active (${state.sessions.filter(s=>!s.archived).length})</button><button class="filter ${state.archive?'active':''}" data-archive="true">Archived (${state.sessions.filter(s=>s.archived).length})</button></div></div>${items.length?`<div class="session-grid">${items.map((s,n)=>`<button class="session-card" data-session="${s.id}"><div class="session-cover">${s.cover?`<img src="${media(s.cover,true)}" alt="${esc(s.details.name)} inspiration" loading="${n?'lazy':'eager'}">`:''}<div class="cover-top"><span class="pill"><span class="dot"></span>${esc(s.details.status)}</span><span class="cover-count">${s.count} references</span></div><div class="cover-bottom"><h3>${esc(s.details.name.split(' · ')[0])}</h3><p>${esc(s.details.name.split(' · ').slice(1).join(' · ')||s.details.description.slice(0,55)||'A new direction waiting to happen.')}</p></div></div><div class="card-footer"><span>${icon('calendar')} ${dateText(s.details.date,true)}</span><span>Open shoot ${icon('arrow')}</span></div></button>`).join('')}</div>`:empty(state.archive?'No archived shoots.':'No shoots here yet.',state.archive?'Archived shoots appear here. Open one to restore it or delete it.':'Your shoots will appear here when they’re ready.','archive',state.archive||!own()?'':'Create a shoot','new-empty')}<div class="dashboard-foot" ${own()?'':'hidden'}>${icon('library')}<span>Your inspiration doesn’t have to start from scratch.</span><button data-screen="library" style="margin-left:auto;font-size:10px;color:var(--text)">Explore your library ${icon('arrow')}</button></div>`}
function bindDashboard(){if($('#new-session'))$('#new-session').onclick=newSession;if($('#new-empty'))$('#new-empty').onclick=newSession;$$('[data-archive]').forEach(b=>b.onclick=()=>{state.archive=b.dataset.archive==='true';render()})}
function empty(title,desc,ic,button,id){return `<div class="empty">${icon(ic||'library')}<h2>${esc(title)}</h2><p>${esc(desc)}</p>${button?btn(ic,button,'btn primary',`id="${id}"`):''}</div>`}
function newSession(){modal(`${modalHead('New shoot')}<form id="new-form"><div class="field"><label for="session-name">Shoot name</label><input id="session-name" name="name" required maxlength="180"></div><div class="modal-actions">${btn('','Cancel','btn ghost','type="button" data-close')}${btn('plus','Create shoot','btn primary','type="submit"')}</div></form>`);$$('[data-close]').forEach(el=>el.onclick=closeModal);$('#new-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const d=await mutate(()=>api('/sessions',{method:'POST',body:Object.fromEntries(new FormData(e.target))}));closeModal();state.sessions=await api('/sessions');await openSession(d.id);toast('A new session, ready for your ideas.')}catch{}finally{b.disabled=false}}}
async function openSession(id){if(!await flushDrafts())return;try{state.session=await api('/sessions/'+id);state.me.role=state.session.role;state.screen='session';state.tab='moodboard';state.view='masonry';state.filter='all';state.search='';selected.clear();undoStack=[];redoStack=[];canvas={zoom:.65,x:35,y:50,pan:matchMedia('(max-width:767px)').matches,snap:true};if(!guestToken){if(state.session.slug)history.replaceState(null,'','/'+state.session.slug);else location.hash='session/'+id;}render();window.scrollTo(0,0)}catch(e){toast(e.message,true)}}
function sessionHTML(){const s=state.session,d=s.details;return `${!own()?`<div class="view-banner">${icon('lock')} A private session with Mario · ${esc(roleText(s.role))}${s.role==='view'?' · You can browse, but cannot make changes.':''}</div>`:''}<div class="session-heading"><div><div class="row"><h1>${esc(d.name)}</h1><span class="pill"><span class="dot"></span>${esc(d.status)}</span></div><div class="session-meta"><span>${icon('calendar')} ${dateText(d.date,true)}${d.start?' · '+timeText(d.start):''}</span><span>${icon('pin')} ${esc(d.location||'Location to be decided')}</span><span>${s.items.filter(i=>i.asset).length} references</span></div></div><div class="session-actions"><div class="avatar-group"><span class="avatar" title="Mario">M</span>${d.participants.split(',').length>1?`<span class="avatar" title="${esc(d.participants.split(',')[1])}" style="background:#6e4f3e">${esc(d.participants.split(',')[1].trim().slice(0,1))}</span>`:''}</div>${btn('day','Shoot day','btn ghost','id="shoot-day"')}${own()?btn('share','Invite','btn','id="invite"')+btn('more','','icon-btn','id="session-menu" aria-label="Session options"'):''}</div></div><nav class="tabs" aria-label="Session views">${[['moodboard','grid','Moodboard'],['details','calendar','Details'],['notes','note','Notes & checklists'],['final','star','Final direction']].map(([t,i,n])=>`<button class="tab ${state.tab===t?'active':''}" data-tab="${t}">${icon(i)}${n}${t==='final'?`<span class="badge-count">${s.items.filter(i=>i.final&&i.asset).length}</span>`:''}</button>`).join('')}</nav><section id="session-body">${state.tab==='moodboard'?boardHTML():state.tab==='details'?detailsHTML():state.tab==='notes'?notesHTML():state.tab==='final'?finalHTML():dayHTML()}</section>`}
function bindSession(){$$('[data-tab]').forEach(b=>b.onclick=async()=>{if(!await flushDrafts())return;state.tab=b.dataset.tab;render()});$('#shoot-day').onclick=async()=>{if(!await flushDrafts())return;state.tab='day';render()};if($('#invite'))$('#invite').onclick=shootAccess;if($('#session-menu'))$('#session-menu').onclick=sessionMenu;if(state.tab==='moodboard')bindBoard();if(state.tab==='details')bindDetails();if(state.tab==='notes')bindNotes();if(state.tab==='final')bindFinal();if(state.tab==='day')bindDay();}
function boardHTML(){return `<div class="board-intro"><div><h2>A feeling worth following.</h2><p>One collection of ideas. Two ways to see it.</p></div><div class="segmented" aria-label="Moodboard layout"><button class="${state.view==='masonry'?'active':''}" data-view="masonry">${icon('grid')}Masonry</button><button class="${state.view==='canvas'?'active':''}" data-view="canvas">${icon('canvas')}Freeform</button></div></div><div class="board-toolbar"><div class="filters">${[['all','All references'],['favorites','Favorites'],['final','Final picks']].map(([id,n])=>`<button class="filter ${state.filter===id?'active':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="row wrap"><label class="search">${icon('search')}<input id="board-search" type="search" aria-label="Search references" placeholder="Find a reference" value="${esc(state.search)}"></label><select id="board-sort" aria-label="Sort references"><option value="newest" ${state.sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${state.sort==='oldest'?'selected':''}>Oldest first</option><option value="favorites" ${state.sort==='favorites'?'selected':''}>Most favorited</option><option value="contributor" ${state.sort==='contributor'?'selected':''}>Contributor</option></select></div></div>${contribute()?`<div class="row between" style="margin-bottom:19px"><span class="board-count" id="board-count">${filteredItems().filter(i=>i.asset).length} references</span><div class="row" style="gap:7px">${own()?btn('library','From library','btn ghost','id="from-library"'):''}${btn('plus','Add inspiration','btn primary','id="upload-board"')}</div></div>`:''}<div id="board-view">${state.view==='canvas'?canvasHTML():masonryHTML(filteredItems())}</div>${state.view==='masonry'&&contribute()?`<button class="upload-drop" style="width:100%" id="upload-drop">${icon('upload')}<span>Drop your inspiration here</span>, or choose photos<small>JPG, PNG or WebP · up to 15 MB per source image</small></button>`:''}`}
function filteredItems(){let items=state.session.items.filter(i=>i.asset);if(state.filter==='favorites')items=items.filter(i=>i.likes.length);if(state.filter==='final')items=items.filter(i=>i.final);const search=state.search.toLowerCase();if(search)items=items.filter(i=>[i.name,i.tags,i.contributor].join(' ').toLowerCase().includes(search));return items.sort((a,b)=>state.sort==='oldest'?a.created-b.created:state.sort==='favorites'?b.likes.length-a.likes.length:state.sort==='contributor'?a.contributor.localeCompare(b.contributor):b.created-a.created)}
function masonryHTML(items,library=false){if(!items.length)return empty(library?'Your references, ready to reuse.':'A little space for inspiration.',library?'Upload photographs to keep them close for your next session.':'Add a photograph, or bring in something from your library.','library');return `<div class="masonry" data-masonry>${items.map((i,n)=>`<article class="reference" data-ratio="${referenceRatio(i)}" data-item="${i.id}" tabindex="-1"><div class="reference-visual"><button class="reference-open" data-open="${i.id}" aria-label="Open ${esc(i.name)}">${photoHTML(i,{library,thumb:true,loading:n<3?'eager':'lazy'})}</button>${!library&&i.final?`<span class="final-label">${icon('check')} FINAL DIRECTION</span>`:''}${!library?`<div class="reference-overlay"></div><div class="ref-actions">${contribute()?`<button class="heart ${i.likes.some(l=>l.mine)?'on':''}" data-like="${i.id}" aria-label="${i.likes.some(l=>l.mine)?'Remove favorite':'Favorite reference'}" aria-pressed="${i.likes.some(l=>l.mine)}">${icon('heart')}</button>`:''}${own()?`<button class="${i.final?'on':''}" data-final="${i.id}" aria-label="${i.final?'Remove from':'Add to'} final direction" aria-pressed="${!!i.final}">${icon('check')}</button>`:''}<button data-open="${i.id}" aria-label="Comments (${i.comments.length})">${icon('comment')}</button></div>`:''}</div><div class="ref-meta"><span class="contributor"><span class="mini">${esc((i.contributor||'M').slice(0,1))}</span>${esc(i.contributor||'Mario')}</span><span>${!library?`${i.likes.length?`${icon('heart')} ${i.likes.length}`:''} ${i.comments.length?`${icon('comment')} ${i.comments.length}`:''}`:esc(i.tags?.split(',')[0]||'Reference')}</span></div><div class="ref-title">${esc(i.name)}</div></article>`).join('')}</div>`}
function layoutMasonry(){ro?.disconnect();const boxes=$$('[data-masonry]');if(!boxes.length)return;const layout=()=>boxes.forEach(box=>{if(!box.isConnected)return;const mobile=window.innerWidth<768,cols=mobile?2:box.clientWidth>1100?4:3,gap=mobile?10:18,w=(box.clientWidth-(cols-1)*gap)/cols,heights=Array(cols).fill(0);$$('.reference',box).forEach(el=>{el.style.width=w+'px';const c=heights.indexOf(Math.min(...heights));el.style.transform=`translate(${c*(w+gap)}px,${heights[c]}px)`;const imageHeight=w/Number(el.dataset.ratio);const metaHeight=$('.ref-meta',el)?.offsetHeight||25;heights[c]+=imageHeight+metaHeight+($('.ref-title',el)?.offsetHeight||17)+ (mobile?19:24)});box.style.height=Math.max(...heights)+'px'});ro=new ResizeObserver(layout);boxes.forEach(b=>ro.observe(b));requestAnimationFrame(layout);$$('img').forEach(img=>img.addEventListener('load',layout,{once:true}))}
function bindBoard(){$$('[data-view]').forEach(b=>b.onclick=async()=>{if(!await flushDrafts())return;state.view=b.dataset.view;state.filter='all';state.search='';render();if(state.view==='canvas')requestAnimationFrame(fitCanvas)});$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});$('#board-search').oninput=e=>{state.search=e.target.value;updateBoardView()};$('#board-sort').onchange=e=>{state.sort=e.target.value;updateBoardView()};if($('#from-library'))$('#from-library').onclick=()=>libraryPicker();if($('#upload-board'))$('#upload-board').onclick=()=>chooseUpload(state.session.id);if($('#upload-drop'))$('#upload-drop').onclick=()=>chooseUpload(state.session.id);bindReferences();}
function updateBoardView(){if(state.view==='canvas'){renderCanvas();return}$('#board-view').innerHTML=masonryHTML(filteredItems());const c=$('#board-count');if(c)c.textContent=`${filteredItems().length} references`;bindReferences();layoutMasonry()}
function bindReferences(root=document){$$('[data-open]',root).forEach(b=>b.onclick=()=>viewer(b.dataset.open));$$('[data-like]',root).forEach(b=>b.onclick=()=>toggleLike(b.dataset.like));$$('[data-final]',root).forEach(b=>b.onclick=()=>toggleFinal(b.dataset.final));}
function findItem(id){return state.session?.items.find(i=>i.id===id)}
async function refreshSession(redraw=true){const s=await api('/sessions/'+state.session.id);state.session=s;if(redraw)render()}
async function toggleLike(id,fromViewer=false){const i=findItem(id);if(!i)return;try{await mutate(()=>api('/items/'+id+'/like',{method:'POST',body:{liked:!i.likes.some(l=>l.mine)}}));await refreshSession(false);if(fromViewer)viewer(id);else if(state.view==='canvas')renderCanvas();else render()}catch{}}
async function toggleFinal(id,fromViewer=false){const i=findItem(id);try{await mutate(async()=>{const r=await api('/items/'+id,{method:'PATCH',body:{final:!i.final,version:i.version}});i.final=!i.final;i.version=r.version});if(fromViewer)viewer(id);else render()}catch{}}
function viewer(id){const library=state.screen==='library';const i=library?state.assets.find(a=>a.id===id):findItem(id);if(!i)return;const references=library?state.assets:state.session.items.filter(a=>a.asset);const index=references.findIndex(a=>a.id===id);modal(`<div class="viewer-image">${photoHTML(i,{library,viewer:true})}${btn('close','','icon-btn viewer-close','data-close aria-label="Close image"')}<div class="viewer-nav">${btn('back','','icon-btn',`data-viewer-prev aria-label="Previous photograph" ${index===0?'disabled':''}`)}${btn('chevron','','icon-btn',`data-viewer-next aria-label="Next photograph" ${index===references.length-1?'disabled':''}`)}</div></div><div class="viewer-side"><h3 id="modal-title">${esc(i.name)}</h3><div class="muted tiny">Added by ${esc(i.contributor)} · ${esc(i.tags||'Inspiration')}</div><div class="row wrap" style="margin-top:18px;gap:7px">${!library&&contribute()?btn('heart',i.likes.some(l=>l.mine)?'Favorited':'Favorite','btn '+(i.likes.some(l=>l.mine)?'primary':''),'id="viewer-like"'):''}${!library&&own()?btn('check',i.final?'Final direction':'Select final','btn '+(i.final?'primary':''),'id="viewer-final"'):''}${!library&&edit()?btn('fit','Crop photo','btn','id="viewer-crop"'):''}${library?btn('plus','Add to a session','btn primary','id="library-add"'):''}</div>${!library?`<div class="comment-list"><div class="eyebrow" style="margin:12px 0 22px">Conversation · ${i.comments.length}</div>${i.comments.length?i.comments.map(c=>`<div class="comment"><strong>${esc(c.name)}</strong><time>${new Date(c.created).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</time><p>${esc(c.body)}</p></div>`).join(''):'<p class="tiny muted">What draws you to this reference?<br>Start the conversation.</p>'}</div>${contribute()?`<form class="comment-form" id="comment-form"><label class="eyebrow" for="comment-body">Add a thought</label><textarea id="comment-body" name="body" placeholder="The light, the feeling, the movement…" required maxlength="2000"></textarea>${btn('arrow','Post comment','btn','type="submit"')}</form>`:''}${own()?`<button class="tiny muted" id="remove-ref" style="text-align:left;margin-top:30px">${icon('trash')} Remove from this session</button>`:''}`:'<p style="margin-top:28px">Reuse this photograph in any session. The stored reference is shared, so there is no second upload.</p>'}</div>`,'viewer');$('[data-viewer-prev]').onclick=()=>viewer(references[index-1]?.id);$('[data-viewer-next]').onclick=()=>viewer(references[index+1]?.id);if($('#viewer-crop'))$('#viewer-crop').onclick=()=>cropEditor(id);if($('#viewer-like'))$('#viewer-like').onclick=()=>toggleLike(id,true);if($('#viewer-final'))$('#viewer-final').onclick=()=>toggleFinal(id,true);if($('#library-add'))$('#library-add').onclick=()=>addLibraryToSession(i.id);if($('#comment-form'))$('#comment-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{await mutate(()=>api('/items/'+id+'/comments',{method:'POST',body:{body:new FormData(e.target).get('body')}}));await refreshSession(false);viewer(id)}catch{}finally{b.disabled=false}};if($('#remove-ref'))$('#remove-ref').onclick=()=>confirmModal('Remove this reference?','It will leave this session. The original stays in your inspiration library.',async()=>{await mutate(()=>api('/items/'+id,{method:'DELETE',body:{}}));await refreshSession();toast('Reference removed. The original is still in your library.')} )}
function confirmModal(title,text,action){modal(`${modalHead(title)}<p>${esc(text)}</p><div class="modal-actions">${btn('','Cancel','btn ghost','data-close')}${btn('check','Confirm','btn primary','id="confirm-action"')}</div>`);$('#confirm-action').onclick=async()=>{const b=$('#confirm-action');b.disabled=true;try{await action();closeModal()}catch(e){toast(e.message,true)}finally{b.disabled=false}}}
function chooseUpload(session){const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.multiple=true;input.onchange=()=>uploadFiles([...input.files],session);input.click()}
async function makeImage(file){if(file.size>15*1024*1024)throw Error(file.name+': source is larger than 15 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error(file.name+': choose JPG, PNG or WebP.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>80e6){bitmap.close();throw Error('This image is too large to process. Export a smaller version.')}const ratio=bitmap.width/bitmap.height;const resize=async max=>{const c=document.createElement('canvas'),scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bitmap,0,0,c.width,c.height);return new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.88))};const large=await resize(2200),thumb=await resize(700);bitmap.close();return {large,thumb,ratio}}
async function uploadFiles(files,session){if(uploading)return;if(!contribute())return;uploading=true;let count=0,errors=[];try{for(let n=0;n<files.length;n++){saveStatus(`Uploading ${n+1} of ${files.length}…`);try{const im=await makeImage(files[n]),fd=new FormData();fd.append('file',im.large,files[n].name.replace(/\.[^.]+$/,'.jpg'));fd.append('thumb',im.thumb,'thumbnail.jpg');fd.append('ratio',im.ratio);await api('/upload'+(session?'?session='+session:''),{method:'POST',body:fd});count++}catch(e){errors.push(e.message)}}if(session&&state.session?.id===session)await refreshSession();else{state.assets=await api('/library');render()}toast(errors.length?`${count} uploaded. ${errors.join(' ')}`:`${count} ${count===1?'reference':'references'} added.`,!!errors.length)}finally{uploading=false;saveStatus()}}
function bindDrop(){const target=$('#content');if(!target||!contribute())return;const valid=()=>state.screen==='library'||(state.screen==='session'&&state.tab==='moodboard');target.ondragover=e=>{if(valid()&&[...e.dataTransfer.types].includes('Files')){e.preventDefault();target.classList.add('drag-over')}};target.ondragleave=e=>{if(!target.contains(e.relatedTarget))target.classList.remove('drag-over')};target.ondrop=e=>{e.preventDefault();target.classList.remove('drag-over');if(valid())uploadFiles([...e.dataTransfer.files],state.screen==='session'?state.session.id:null)}}
document.addEventListener('paste',e=>{if(!state.me||!contribute()||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(state.screen!=='library'&&!(state.screen==='session'&&state.tab==='moodboard'))return;const files=[...e.clipboardData.items].filter(i=>i.type.startsWith('image/')).map(i=>i.getAsFile());if(files.length){e.preventDefault();uploadFiles(files,state.screen==='session'?state.session.id:null)}});
function detailsHTML(){const d=state.session.details,readonly=!own();const field=(name,label,type='text',full=false)=>`<div class="field ${full?'full':''}"><label for="detail-${name}">${label}</label>${type==='textarea'?`<textarea id="detail-${name}" name="${name}" ${readonly?'readonly':''} ${name==='description'?'style="min-height:140px"':''}>${esc(d[name])}</textarea>`:`<input id="detail-${name}" name="${name}" type="${type}" value="${esc(d[name])}" ${readonly?'readonly':''} ${name==='name'?'required':''}>`}</div>`;return `<div class="details-layout"><form id="details-form"><div class="section-heading"><h2>The shape of the session.</h2><span class="tiny muted" id="detail-save-hint">${own()?'Saved as you finish each field':'Session information'}</span></div><div class="form-grid">${field('name','Shoot name','text',true)}${field('participants','Participants','text',true)}${field('date','Shoot date','date')}<div class="field"><label for="detail-status">Status</label><select id="detail-status" name="status" ${readonly?'disabled':''}>${['Planning','Confirmed','Completed'].map(s=>`<option ${s===d.status?'selected':''}>${s}</option>`).join('')}</select></div>${field('start','Start time','time')}${field('end','End time','time')}${field('timezone','Time zone (IANA name)','text',true)}${field('location','Location name','text',true)}${field('address','Meeting address','text',true)}${field('description','Creative concept','textarea',true)}</div>${own()?`<div class="row between" style="margin-top:25px"><span class="tiny muted">A plan that can grow with the idea.</span>${btn('check','Save details','btn primary','type="submit"')}</div>`:''}<div class="error" id="details-error"></div></form><aside class="info-card"><h3>The essentials</h3>${sessionInfoHTML(d)}<hr>${btn('calendar','Add to calendar','btn','id="calendar-menu" style="width:100%"')}<p class="tiny muted" style="font-size:10px;margin-top:14px;line-height:1.8">Take the plan with you. Calendar events use the session’s time zone.</p></aside></div>`}
function sessionInfoHTML(d){return `<div class="info-line">${icon('calendar')}<div><strong>${dateText(d.date)}</strong>${d.start?timeText(d.start)+(d.end?' – '+timeText(d.end):''):'Time to be decided'}<br>${esc(d.timezone||'America/Chicago')}</div></div><div class="info-line">${icon('pin')}<div><strong>${esc(d.location||'Location to be decided')}</strong>${esc(d.address)}${d.address?`<br><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(d.address)}" target="_blank" rel="noopener" style="text-decoration:underline;display:inline-block;margin-top:8px">Get directions ${icon('arrow')}</a>`:''}</div></div><div class="info-line">${icon('comment')}<div><strong>Making it together</strong>${esc(d.participants||'Mario Romay')}</div></div>`}
function bindDetails(){if($('#calendar-menu'))$('#calendar-menu').onclick=calendarMenu;const form=$('#details-form');if(!own())return;let saving=false;const save=async()=>{if(saving)return;if(!form.reportValidity())return;saving=true;const values=Object.fromEntries(new FormData(form));try{const sent=JSON.stringify(values);await mutate(async()=>{const r=await api('/sessions/'+state.session.id,{method:'PATCH',body:{version:state.session.version,details:{...state.session.details,...values},archived:state.session.archived}});state.session.version=r.version;state.session.details={...state.session.details,...values}});dirty=JSON.stringify(Object.fromEntries(new FormData(form)))!==sent;$('#details-error').textContent='';$('#detail-save-hint').textContent=dirty?'Unsaved edits':'All details saved';if(!dirty)$('.session-heading h1').textContent=state.session.details.name}catch(e){dirty=true;$('#details-error').textContent=e.message;$('#detail-save-hint').textContent='Unsaved edits · draft kept'}finally{saving=false}};form.oninput=()=>{dirty=true;$('#detail-save-hint').textContent='Unsaved changes'};form.addEventListener('change',save);form.onsubmit=e=>{e.preventDefault();save()}}
function notesHTML(){const notes=state.session.notes;return `<div class="notes-layout ${own()?'':'one'}">${notes.map(n=>`<section class="note-panel" data-note="${n.kind}"><div class="section-heading"><h2>${n.kind==='private'?'Just for you.':'On the same page.'}</h2><span class="private-label">${icon(n.kind==='private'?'lock':'share')}${n.kind==='private'?'Private':'Shared'}</span></div><div class="row between" style="margin-bottom:16px"><span class="tiny muted">${n.kind==='private'?'Your equipment, lighting, and reminders.':'Wardrobe, locations, and little reminders.'}</span>${contribute()?btn('edit','','icon-btn',`data-edit-note="${n.kind}" aria-label="Edit ${n.kind} notes"`):''}</div><div class="note-preview" data-note-preview="${n.kind}">${markdown(n.body,n.kind,contribute())}</div><div class="hidden" data-note-editor="${n.kind}"><label class="eyebrow" for="note-${n.kind}">Use # headings, - [ ] checklists, and links</label><textarea id="note-${n.kind}" aria-label="${n.kind} notes" style="margin-top:12px">${esc(n.body)}</textarea><div class="row between" style="margin-top:14px"><span class="tiny muted" data-note-status="${n.kind}">Autosaves after you pause</span>${btn('check','Done','btn',`data-done-note="${n.kind}"`)}</div></div></section>`).join('')}</div>`}
function markdown(text,kind,interactive=false){if(!text.trim())return '<p class="muted">A blank page for the ideas still taking shape.</p>';return text.split('\n').map((line,idx)=>{const check=line.match(/^- \[([ xX])\] (.*)$/);if(check)return `<label class="check-line"><input type="checkbox" data-check-kind="${kind}" data-line="${idx}" ${check[1].toLowerCase()==='x'?'checked':''} ${interactive?'':'disabled'}><span>${inlineMarkdown(check[2])}</span></label>`;const heading=line.match(/^(#{1,3}) (.*)$/);if(heading)return `<h${Math.min(heading[1].length+1,3)}>${esc(heading[2])}</h${Math.min(heading[1].length+1,3)}>`;return line?`<p>${inlineMarkdown(line)}</p>`:'<div style="height:7px"></div>'}).join('')}
function inlineMarkdown(s){return esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>`<a href="${esc(safeUrl(url.replaceAll('&amp;','&')))}" target="_blank" rel="noopener">${label}</a>`)}
const noteTimers=new Map();
async function saveNote(kind,text){const note=state.session.notes.find(n=>n.kind===kind);return mutate(async()=>{const r=await api('/sessions/'+state.session.id+'/notes/'+kind,{method:'PATCH',body:{version:note.version,body:text}});note.body=text;note.version=r.version})}
function bindChecks(){$$('[data-check-kind]').forEach(input=>input.onchange=async()=>{const kind=input.dataset.checkKind,note=state.session.notes.find(n=>n.kind===kind),lines=note.body.split('\n');lines[Number(input.dataset.line)]=lines[Number(input.dataset.line)].replace(/^- \[[ xX]\]/,input.checked?'- [x]':'- [ ]');try{await saveNote(kind,lines.join('\n'));input.parentElement.classList.toggle('checked',input.checked)}catch{input.checked=!input.checked}})}
function bindNotes(){bindChecks();$$('[data-edit-note]').forEach(b=>b.onclick=()=>{const kind=b.dataset.editNote;$(`[data-note-preview="${kind}"]`).classList.add('hidden');$(`[data-note-editor="${kind}"]`).classList.remove('hidden');b.classList.add('hidden');$(`#note-${kind}`).focus()});$$('[data-done-note]').forEach(b=>b.onclick=async()=>{const kind=b.dataset.doneNote;clearTimeout(noteTimers.get(kind));const editor=$('#note-'+kind);b.disabled=true;try{if(editor.value!==state.session.notes.find(n=>n.kind===kind).body)await saveNote(kind,editor.value);dirty=$$('textarea', $('#session-body')).some(t=>t.value!==state.session.notes.find(n=>n.kind===t.id.replace('note-',''))?.body);$(`[data-note-preview="${kind}"]`).innerHTML=markdown(editor.value,kind,contribute());$(`[data-note-preview="${kind}"]`).classList.remove('hidden');$(`[data-note-editor="${kind}"]`).classList.add('hidden');$(`[data-edit-note="${kind}"]`).classList.remove('hidden');bindChecks()}catch{}finally{b.disabled=false}});$$('textarea[id^=note-]').forEach(t=>t.oninput=()=>{const kind=t.id.slice(5);dirty=true;const status=$(`[data-note-status="${kind}"]`);status.textContent='Saving…';clearTimeout(noteTimers.get(kind));noteTimers.set(kind,setTimeout(async()=>{const text=t.value;try{await saveNote(kind,text);dirty=$$('textarea[id^=note-]').some(t=>t.value!==state.session.notes.find(n=>n.kind===t.id.slice(5))?.body);status.textContent=dirty?'Unsaved changes':'All notes saved'}catch{dirty=true;status.textContent='Could not save · draft kept'}},800))})}
function finalHTML(){const s=state.session,d=s.details,items=s.items.filter(i=>i.final&&i.asset);return `<div class="direction-controls"><span class="eyebrow">The direction, together</span><div class="row">${own()?btn('edit','Edit direction','btn ghost','id="edit-direction"'):''}${btn('download','Save as PDF','btn','id="export-pdf"')}${btn('library','PNG','btn ghost','id="export-png"')}</div></div><div id="final-presentation"><div class="direction-header"><span class="eyebrow">${esc(d.participants||'Mario Romay')} · Creative direction</span><h2>${esc(d.name)}</h2><p>${esc(d.direction||d.description||'Our shared creative direction, gathered in one place.')}</p><div class="session-meta"><span>${icon('calendar')} ${dateText(d.date)}${d.start?' · '+timeText(d.start):''}</span><span>${icon('pin')} ${esc(d.location)}</span></div></div>${items.length?masonryHTML(items):empty('Let the direction take shape.','Use the checkmark on a reference to include it in this shared selection.','star')}</div>`}
function bindFinal(){bindReferences();if($('#edit-direction'))$('#edit-direction').onclick=editDirection;$('#export-pdf').onclick=()=>window.print();$('#export-png').onclick=exportPNG}
function editDirection(){modal(`${modalHead('The feeling we’re following.')}<p>A few words to bring the final references together.</p><form id="direction-form"><div class="field"><label for="direction-note">Creative direction</label><textarea id="direction-note" style="min-height:180px" maxlength="5000">${esc(state.session.details.direction)}</textarea></div><div class="modal-actions">${btn('check','Save direction','btn primary','type="submit"')}</div></form>`);$('#direction-form').onsubmit=async e=>{e.preventDefault();try{const details={...state.session.details,direction:$('#direction-note').value};await mutate(async()=>{const r=await api('/sessions/'+state.session.id,{method:'PATCH',body:{details,version:state.session.version,archived:state.session.archived}});state.session.details=details;state.session.version=r.version});closeModal();render()}catch{}}}
async function exportPNG(){const items=state.session.items.filter(i=>i.final&&i.asset);if(!items.length){toast('Select a few final references first.');return}toast('Preparing your final direction…');try{const width=1800,gap=28,colW=(width-120-2*gap)/3,images=await Promise.all(items.map(async i=>{const blob=await (await fetch(media(i.asset))).blob();return {i,img:await createImageBitmap(blob)}}));const positions=[],heights=[380,380,380];for(const p of images){const c=heights.indexOf(Math.min(...heights)),h=colW/referenceRatio(p.i);positions.push({...p,x:60+c*(colW+gap),y:heights[c],w:colW,h});heights[c]+=h+gap}const c=document.createElement('canvas');c.width=width;c.height=Math.max(...heights)+55;if(c.height>16000)throw Error('This selection is too large for PNG. Use Save as PDF.');const ctx=c.getContext('2d');ctx.fillStyle='#f3f2ed';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#535e47';ctx.font='18px Arial';ctx.fillText('SHOOTS / CREATIVE DIRECTION',60,65);ctx.fillStyle='#1d251a';ctx.font='48px Arial';ctx.fillText(state.session.details.name,60,140,width-120);ctx.font='22px Arial';let y=195;const words=(state.session.details.direction||state.session.details.description||'').split(/\s+/);let line='';for(const word of words){if(ctx.measureText(line+word).width>width-120){ctx.fillText(line,60,y);y+=31;line=''}line+=word+' ';if(y>280)break}ctx.fillText(line,60,y);ctx.font='18px Arial';ctx.fillStyle='#535e47';ctx.fillText(`${dateText(state.session.details.date)} · ${state.session.details.location}`,60,342);for(const p of positions){const source=cropSourceRect(p.img.width,p.img.height,p.i.transform?.crop);ctx.drawImage(p.img,source.x,source.y,source.w,source.h,p.x,p.y,p.w,p.h);p.img.close()}c.toBlob(blob=>{download(blob,'shoots-final-direction.png');toast('Final direction exported.')} ,'image/png')}catch(e){toast(e.message,true)}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function dayHTML(){const d=state.session.details;return `<div class="shoot-day"><div class="eyebrow">Less planning. More photographing.</div><h1 style="margin-top:12px">${esc(d.name)}</h1><div class="day-cards"><div class="info-card">${sessionInfoHTML(d)}${btn('calendar','Add to calendar','btn','id="day-calendar"')}</div><div class="info-card"><h3>The direction</h3><p class="muted" style="font-size:12px;white-space:pre-wrap;line-height:1.9">${esc(d.direction||d.description)}</p></div></div><div class="day-final"><div class="section-heading"><h2>Keep the feeling close.</h2><span class="tiny muted">Final references</span></div>${masonryHTML(state.session.items.filter(i=>i.final&&i.asset))}</div>${state.session.notes.map(n=>`<div class="note-panel" style="margin-top:18px"><div class="section-heading"><h2>${n.kind==='private'?'Your reminders':'Shared notes'}</h2><span class="private-label">${icon(n.kind==='private'?'lock':'share')}${n.kind==='private'?'Only you':'Everyone'}</span></div><div class="note-preview">${markdown(n.body,n.kind,contribute())}</div></div>`).join('')}</div>`}
function bindDay(){bindReferences();bindChecks();$('#day-calendar').onclick=calendarMenu}
function calendarMenu(){const d=state.session.details;if(!d.date||!d.start||!d.end){toast('Add the date, start time, and end time in Details first.',true);return}const start=toUTC(d.date,d.start,d.timezone),end=toUTC(d.date,d.end,d.timezone);if(end<=start){toast('The end time must be after the start time.',true);return}const sessionURL=location.origin+(guestToken?'/g/'+guestToken:'/#session/'+state.session.id);const desc=(d.description||'')+'\nSession: '+sessionURL;const fmt=dt=>dt.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const google='https://calendar.google.com/calendar/render?'+new URLSearchParams({action:'TEMPLATE',text:d.name,dates:fmt(start)+'/'+fmt(end),ctz:d.timezone,location:d.address||d.location,details:desc});const outlook='https://outlook.live.com/calendar/0/deeplink/compose?'+new URLSearchParams({subject:d.name,startdt:start.toISOString(),enddt:end.toISOString(),location:d.address||d.location,body:desc});modal(`${modalHead('Take the plan with you.')}<p>${dateText(d.date)} · ${timeText(d.start)} – ${timeText(d.end)}<br>${esc(d.timezone)} · ${esc(d.location)}</p><div class="stack" style="margin-top:24px"><a class="btn" href="${esc(google)}" target="_blank" rel="noopener">${icon('calendar')} Google Calendar</a><button class="btn" id="calendar-ics">${icon('download')} Apple Calendar / .ics download</button><a class="btn" href="${esc(outlook)}" target="_blank" rel="noopener">${icon('calendar')} Outlook</a></div><p style="margin-top:20px;font-size:10px">The event includes shared session details and its URL. Private notes are never included.</p>`);$('#calendar-ics').onclick=()=>{const escapeICS=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Shoots//Session Planner//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+state.session.id+'@shoots.marioromay.com','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:'+escapeICS(d.name),'LOCATION:'+escapeICS(d.address||d.location),'DESCRIPTION:'+escapeICS(desc),'URL:'+sessionURL,'END:VEVENT','END:VCALENDAR'];const folded=lines.map(l=>{let out='',current='',size=0;for(const ch of l){const n=new TextEncoder().encode(ch).length;if(size+n>72){out+=current+'\r\n ';current='';size=1}current+=ch;size+=n}return out+current}).join('\r\n')+'\r\n';download(new Blob([folded],{type:'text/calendar;charset=utf-8'}),'shoots-session.ics')}}
function toUTC(date,time,tz){const wall=new Date(date+'T'+time+':00Z');let out=wall;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(out).map(p=>[p.type,p.value]));const shown=Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second);out=new Date(out.getTime()+wall.getTime()-shown)}return out}
async function sharing(){let links;try{links=await api('/sessions/'+state.session.id+'/links')}catch(e){toast(e.message,true);return}modal(`${modalHead('Bring someone into the idea.')}<p>A private invitation to ${esc(state.session.details.name)}. No client account required.</p><form id="share-form">${[['view','View only','Browse references, details, and shared notes.'],['contribute','Contribute','Upload, comment, favorite, and edit shared notes.'],['collaborate','Collaborate','Everything above, plus arranging the freeform canvas.']].map(([v,t,sub])=>`<label class="share-option"><input type="radio" name="role" value="${v}" ${v==='contribute'?'checked':''}><span><strong>${t}</strong><small>${sub}</small></span></label>`).join('')}<div class="field"><label for="share-pin">Optional PIN · 4–8 digits</label><input id="share-pin" name="pin" inputmode="numeric" pattern="[0-9]{4,8}" minlength="4" maxlength="8" placeholder="A little extra privacy" autocomplete="off"></div><div class="modal-actions">${btn('link','Create invitation link','btn primary','type="submit"')}</div></form><div id="created-link"></div>${links.filter(l=>l.active).length?'<hr><div class="eyebrow" style="margin-bottom:12px">Active invitations</div>':''}${links.filter(l=>l.active).map(l=>`<div class="link-row"><div><span class="tiny">${roleText(l.role)} ${l.pin?'· PIN protected':''}</span><p>Created ${new Date(l.created).toLocaleDateString()}</p></div><div class="row" style="gap:3px">${btn('copy','','icon-btn',`data-copy-link="${l.token}" aria-label="Copy invitation link"`)}${btn('trash','','icon-btn',`data-revoke="${l.token}" aria-label="Revoke invitation link"`)}</div></div>`).join('')}<p style="font-size:10px;margin-top:20px">Private notes and your inspiration library stay private. Revoking a link also ends access for people who already joined.</p>`);$('#share-form').onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{const r=await api('/sessions/'+state.session.id+'/links',{method:'POST',body:Object.fromEntries(new FormData(e.target))});const url=location.origin+'/g/'+r.token;$('#created-link').innerHTML=`<hr><div class="field"><label for="new-invite-url">Your new invitation</label><input class="link-box" id="new-invite-url" readonly value="${esc(url)}"></div><div class="row">${btn('copy','Copy link','btn primary','id="copy-created"')}${navigator.share?btn('share','Share','btn','id="native-share"'):''}<a class="btn" href="${url}" target="_blank" rel="noopener">Preview as guest ${icon('arrow')}</a></div>`;$('#copy-created').onclick=()=>copyText(url);if($('#native-share'))$('#native-share').onclick=()=>navigator.share({title:state.session.details.name,url}).catch(()=>{});toast('Invitation created.')}catch(e){toast(e.message,true)}finally{button.disabled=false}};$$('[data-copy-link]').forEach(b=>b.onclick=()=>copyText(location.origin+'/g/'+b.dataset.copyLink));$$('[data-revoke]').forEach(b=>b.onclick=()=>confirmModal('Revoke this invitation?','Everyone using this link will lose access, including guests who already joined. Create a new link to invite them again.',async()=>{await api('/links/'+b.dataset.revoke,{method:'DELETE',body:{}});toast('Invitation revoked.')}))}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Link copied.')}catch{modal(`${modalHead('Copy this link')}<input class="link-box" readonly value="${esc(s)}" id="copy-fallback"><p style="margin-top:12px">Select the link and copy it to share.</p>`);$('#copy-fallback').select()}}
function sessionMenu(){modal(`${modalHead('Session options')}<p style="margin-bottom:20px">${esc(state.session.details.name)}</p><div class="session-menu">${btn('copy','Duplicate session','btn','id="duplicate-session"')}${btn('archive',state.session.archived?'Restore session':'Archive session','btn','id="archive-session"')}${btn('trash','Delete session','btn danger','id="delete-session"')}</div><p style="margin-top:18px;font-size:10px">Duplicating reuses references without copying stored images. Guest links are never copied.</p>`);$('#duplicate-session').onclick=async()=>{try{const r=await mutate(()=>api('/sessions/'+state.session.id+'/duplicate',{method:'POST',body:{}}));closeModal();state.sessions=await api('/sessions');await openSession(r.id);toast('Session duplicated.')}catch{}};$('#delete-session').onclick=deleteSession;$('#archive-session').onclick=()=>confirmModal(state.session.archived?'Restore this session?':'Archive this session?',state.session.archived?'Move it back to your active sessions.':'Keep the session and its photographs, and move it out of your active list. Guest links remain active until you revoke them.',async()=>{await mutate(()=>api('/sessions/'+state.session.id,{method:'PATCH',body:{details:state.session.details,version:state.session.version,archived:!state.session.archived}}));await navigate('sessions');toast('Session updated.')})}
function libraryHTML(){const search=state.librarySearch.toLowerCase(),assets=state.assets.filter(a=>[a.name,a.tags,a.contributor].join(' ').toLowerCase().includes(search));return `<div class="library-head"><div><div class="eyebrow">Collected along the way</div><h1>Your inspiration library.</h1><p>Good ideas are worth keeping. Reuse them in any session.</p></div>${btn('plus','Add references','btn primary','id="upload-library"')}</div><div class="board-toolbar"><span class="tiny muted">${state.assets.length} saved references · only visible to you</span><label class="search">${icon('search')}<input id="library-search" value="${esc(state.librarySearch)}" placeholder="Search names, tags, contributors" type="search" aria-label="Search library" style="width:225px"></label></div><div id="library-grid">${masonryHTML(assets,true)}</div>`}
function bindLibrary(){$('#upload-library').onclick=()=>chooseUpload();$('#library-search').oninput=e=>{state.librarySearch=e.target.value;const search=e.target.value.toLowerCase();$('#library-grid').innerHTML=masonryHTML(state.assets.filter(a=>[a.name,a.tags,a.contributor].join(' ').toLowerCase().includes(search)),true);bindReferences();layoutMasonry()};bindReferences()}
async function libraryPicker(){try{state.assets=await api('/library');const used=new Set(state.session.items.map(i=>i.asset));modal(`${modalHead('Something from your collection.')}<p>Add references without uploading them again.</p><label class="search" style="margin-top:15px">${icon('search')}<input id="library-picker-search" placeholder="Search your references" style="width:100%"></label><div class="library-select-grid" id="library-picks"></div>`,'library-modal');const draw=(search='')=>{$('#library-picks').innerHTML=state.assets.filter(a=>[a.name,a.tags].join(' ').toLowerCase().includes(search.toLowerCase())).map(a=>`<button class="library-pick ${used.has(a.id)?'used':''}" data-pick="${a.id}" ${used.has(a.id)?'disabled':''}><img src="${media(a.id,true)}" alt="${esc(a.name)}" loading="lazy"><span>${used.has(a.id)?'Already on this board':esc(a.name)}</span></button>`).join('');$$('[data-pick]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const a=state.assets.find(a=>a.id===b.dataset.pick);await mutate(()=>api('/sessions/'+state.session.id+'/items',{method:'POST',body:{asset:a.id,transform:{x:80+state.session.items.length*20,y:80,w:280,h:280/a.ratio,z:state.session.items.length+1}}}));used.add(a.id);await refreshSession(false);draw($('#library-picker-search').value);toast('Reference added to the session.')}catch{b.disabled=false}})};draw();$('#library-picker-search').oninput=e=>draw(e.target.value);modalCleanup=()=>{render()}}catch(e){toast(e.message,true)}}
async function addLibraryToSession(asset){state.sessions=await api('/sessions');modal(`${modalHead('Add to a session')}<p>Reuse this reference without making another copy.</p><div class="stack" style="margin-top:20px">${state.sessions.filter(s=>!s.archived).map(s=>`<button class="btn" data-library-session="${s.id}" style="justify-content:space-between">${esc(s.details.name)}${icon('plus')}</button>`).join('')||'<p>Create a session first.</p>'}</div>`);$$('[data-library-session]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/sessions/'+b.dataset.librarySession+'/items',{method:'POST',body:{asset,transform:{w:280,h:280/(state.assets.find(a=>a.id===asset)?.ratio||.75)}}});closeModal();toast('Reference added.')}catch(e){toast(e.message,true);b.disabled=false}})}
function canvasHTML(){return `<div class="canvas-wrap"><div class="canvas-viewport ${canvas.pan?'panning':''}" id="canvas-viewport" tabindex="0" role="application" aria-label="Freeform moodboard. Select a reference, use arrow keys to move it. Hold Space or use Hand to pan."><div class="canvas-world" id="canvas-world"></div></div><div class="canvas-tools" aria-label="Canvas tools">${btn('cursor','','icon-btn '+(!canvas.pan?'active':''),'id="tool-select" title="Select and move" aria-label="Select and move"')}${btn('hand','','icon-btn '+(canvas.pan?'active':''),'id="tool-pan" title="Pan · hold Space" aria-label="Pan canvas"')}${edit()?`<span class="tool-divider"></span>${btn('text','','icon-btn','id="add-text" title="Text card" aria-label="Add text card"')}${btn('palette','','icon-btn','id="add-swatch" title="Color swatch" aria-label="Add color swatch"')}${btn('link','','icon-btn','id="add-link" title="Link card" aria-label="Add link card"')}<span class="tool-divider"></span>${btn('undo','','icon-btn',`id="undo" title="Undo" aria-label="Undo" ${!undoStack.length?'disabled':''}`)}${btn('redo','','icon-btn',`id="redo" title="Redo" aria-label="Redo" ${!redoStack.length?'disabled':''}`)}`:''}</div><div id="canvas-inspector"></div><div class="canvas-bottom"><div class="zoom-tools">${btn('minus','','icon-btn','id="zoom-out" aria-label="Zoom out"')}<span id="zoom-value" style="min-width:38px;text-align:center">${Math.round(canvas.zoom*100)}%</span>${btn('plus','','icon-btn','id="zoom-in" aria-label="Zoom in"')}${btn('fit','','icon-btn','id="zoom-fit" aria-label="Fit board to view"')}<span class="tool-divider" style="height:18px"></span><button id="snap-toggle" style="padding:0 8px;font-size:9px" aria-pressed="${canvas.snap}">Snap ${canvas.snap?'on':'off'}</button></div><span class="canvas-hint">Drag to arrange · Shift to select together · Space to pan · scroll to zoom</span></div></div>`}
function canvasItems(){if(state.filter==='all'&&!state.search)return state.session.items;const allowed=new Set(filteredItems().map(i=>i.id));return state.session.items.filter(i=>allowed.has(i.id))}
function nodeHTML(i){const t=i.transform,sel=selected.has(i.id);const inner=i.asset?`${photoHTML(i,{canvas:true,thumb:true})}`:i.kind==='swatch'?`<div class="swatch-body">${esc(i.body||t.color)}</div>`:i.kind==='link'?`<div class="node-link">${icon('link')}<span>${esc(i.body)}</span></div>`:`<div class="node-text">${esc(i.body)}</div>`;return `<div class="canvas-node ${sel?'selected':''}" data-node="${i.id}" role="button" tabindex="0" aria-label="${esc(i.name||i.kind+' card')}" style="${nodeStyle(t,i)}">${inner}${sel&&edit()?`<span class="resize-handle" data-handle="resize" title="Drag to resize"></span><span class="rotate-handle" data-handle="rotate" title="Drag to rotate"></span>`:''}</div>`}
function nodeStyle(t,i){return `left:${t.x}px;top:${t.y}px;width:${t.w}px;height:${t.h}px;transform:rotate(${t.r}deg);z-index:${t.z};opacity:${t.opacity??1};border:${t.border||0}px solid ${t.color||'#eee'};border-radius:${t.radius||0}px;background:${i.asset?'transparent':t.color||'#d1bda1'};`}
function renderCanvas(){if(!$('#canvas-world'))return;$('#canvas-world').innerHTML=canvasItems().map(nodeHTML).join('');applyCamera();bindCanvas();renderInspector()}
function applyCamera(){const world=$('#canvas-world');if(world)world.style.transform=`translate(${canvas.x}px,${canvas.y}px) scale(${canvas.zoom})`;if($('#zoom-value'))$('#zoom-value').textContent=Math.round(canvas.zoom*100)+'%';$('#canvas-viewport')?.classList.toggle('panning',canvas.pan);$('#tool-pan')?.classList.toggle('active',canvas.pan);$('#tool-select')?.classList.toggle('active',!canvas.pan)}
function fitCanvas(){const v=$('#canvas-viewport');if(!v)return;const items=canvasItems();if(!items.length){canvas.x=25;canvas.y=65;canvas.zoom=.7;applyCamera();return}const minX=Math.min(...items.map(i=>i.transform.x)),minY=Math.min(...items.map(i=>i.transform.y)),maxX=Math.max(...items.map(i=>i.transform.x+i.transform.w)),maxY=Math.max(...items.map(i=>i.transform.y+i.transform.h)),w=v.clientWidth,h=v.clientHeight;canvas.zoom=Math.max(.15,Math.min(.95,(w-70)/(maxX-minX+35),(h-130)/(maxY-minY+40)));canvas.x=(w-(maxX-minX)*canvas.zoom)/2-minX*canvas.zoom;canvas.y=65+(h-130-(maxY-minY)*canvas.zoom)/2-minY*canvas.zoom;applyCamera()}
function zoomBy(mult,cx,cy){const v=$('#canvas-viewport');if(!v)return;cx=cx??v.clientWidth/2;cy=cy??v.clientHeight/2;const before=canvas.zoom;canvas.zoom=Math.min(2.5,Math.max(.15,canvas.zoom*mult));canvas.x=cx-(cx-canvas.x)*(canvas.zoom/before);canvas.y=cy-(cy-canvas.y)*(canvas.zoom/before);applyCamera()}
