vp.onpointerdown=e=>{if(e.button===2)return;const box=vp.getBoundingClientRect();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});vp.setPointerCapture(e.pointerId);if(pointers.size===2){const a=[...pointers.values()];pinch={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),cx:(a[0].x+a[1].x)/2-box.left,cy:(a[0].y+a[1].y)/2-box.top,zoom:canvas.zoom,x:canvas.x,y:canvas.y};if(drag?.type==='item'){for(const c of drag.changes)c.i.transform=c.before;renderNodes()}drag=null;return}const node=e.target.closest('[data-node]'),handle=e.target.closest('[data-handle]');if(canvas.pan||e.button===1||(!node&&e.pointerType==='touch')){drag={type:'pan',x:e.clientX,y:e.clientY,cx:canvas.x,cy:canvas.y};return}if(node){const id=node.dataset.node,i=findItem(id);if(e.shiftKey){selected.has(id)?selected.delete(id):selected.add(id)}else if(!selected.has(id)){selected.clear();selected.add(id)}if(i.transform.group&&!e.shiftKey)for(const other of state.session.items)if(other.transform.group===i.transform.group)selected.add(other.id);renderNodes();renderInspector();if(!edit())return;drag={type:'item',mode:handle?.dataset.handle||'move',id,x:e.clientX,y:e.clientY,changes:[...selected].map(id=>findItem(id)).filter(Boolean).map(i=>({i,before:structuredClone(i.transform)})),center:{x:box.left+canvas.x+(i.transform.x+i.transform.w/2)*canvas.zoom,y:box.top+canvas.y+(i.transform.y+i.transform.h/2)*canvas.zoom}};drag.startAngle=Math.atan2(e.clientY-drag.center.y,e.clientX-drag.center.x)*180/Math.PI}else{selected.clear();renderNodes();renderInspector();drag={type:'pan',x:e.clientX,y:e.clientY,cx:canvas.x,cy:canvas.y}}};
