function bindNodes(){$$('[data-node]').forEach(el=>{el.ondblclick=()=>{const i=findItem(el.dataset.node);if(i.asset)viewer(i.id);else if(edit())editCard(i.id);else if(i.kind==='link')window.open(safeUrl(i.body),'_blank','noopener')};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selected.clear();selected.add(el.dataset.node);renderNodes();renderInspector()}}})}
