function changeTransform(i,changes){return applyChanges([{i,before:structuredClone(i.transform),after:{...i.transform,...changes}}])}
async function applyChanges(changes){for(const c of changes)c.i.transform=structuredClone(c.after);renderNodes();renderInspector();return persistChanges(changes,true)}
async function persistChanges(changes,history){for(const c of changes)c.i.transform=structuredClone(c.after);let success=[];try{await mutate(async()=>{for(const c of changes){const i=findItem(c.i.id);const r=await api('/items/'+i.id,{method:'PATCH',body:{version:i.version,transform:c.after}});i.version=r.version;success.push(c)}});if(history){undoStack.push(success.map(c=>({id:c.i.id,before:c.before,after:c.after})));if(undoStack.length>50)undoStack.shift();redoStack=[]}}catch(e){for(const c of changes)if(!success.includes(c))c.i.transform=c.before;toast('An edit could not be saved. Reload to review the latest board.',true)}finally{if($('#undo'))$('#undo').disabled=!undoStack.length;if($('#redo'))$('#redo').disabled=!redoStack.length;renderNodes();renderInspector()}}
async function historyMove(redo){if(!edit()||state.busy)return;const from=redo?redoStack:undoStack,to=redo?undoStack:redoStack,entry=from.pop();if(!entry)return;const changes=entry.map(c=>({i:findItem(c.id),before:structuredClone(findItem(c.id)?.transform),after:structuredClone(redo?c.after:c.before)})).filter(c=>c.i);await persistChanges(changes,false);to.push(entry);renderCanvas()}
function addCard(kind){modal(`${modalHead(kind==='text'?'Words that set the tone.':kind==='swatch'?'A color to come back to.':'Keep a reference close.')}<form id="card-form"><div class="field"><label for="card-body">${kind==='link'?'Reference URL':kind==='swatch'?'Color name or note':'Your note'}</label>${kind==='text'?'<textarea id="card-body" required placeholder="The feeling, the light, the little details…" style="min-height:170px"></textarea>':`<input id="card-body" ${kind==='link'?'type="url" required placeholder="https://…"':'placeholder="Warm cream"'}>`}</div><div class="field"><label for="card-color">Card color</label><input id="card-color" type="color" value="${kind==='swatch'?'#a97252':'#d7c5a6'}"></div><div class="modal-actions">${btn('plus','Add to canvas','btn primary','type="submit"')}</div></form>`);$('#card-form').onsubmit=async e=>{e.preventDefault();const body=$('#card-body').value;if(kind==='link'&&safeUrl(body)==='#'){toast('Use an http or https URL.',true);return}const color=$('#card-color').value;try{await mutate(()=>api('/sessions/'+state.session.id+'/items',{method:'POST',body:{kind,body:body||(kind==='swatch'?color:''),transform:{x:Math.max(0,(180-canvas.x)/canvas.zoom),y:Math.max(0,(100-canvas.y)/canvas.zoom),w:300,h:kind==='swatch'?220:kind==='link'?170:240,color,z:Math.max(0,...state.session.items.map(i=>i.transform.z))+1}}}));closeModal();await refreshSession();toast('Card added to your canvas.')}catch{}}}
function editCard(id){const i=findItem(id);if(!i||!edit())return;modal(`${modalHead('A few words, a clear feeling.')}<form id="edit-card-form"><div class="field"><label for="edit-card-body">${i.kind==='link'?'Reference URL':'Card text'}</label><textarea id="edit-card-body" style="min-height:160px">${esc(i.body)}</textarea></div>${i.kind==='link'?`<a class="btn" href="${esc(safeUrl(i.body))}" target="_blank" rel="noopener">${icon('link')} Open reference</a>`:''}<div class="modal-actions">${btn('check','Save card','btn primary','type="submit"')}</div></form>`);$('#edit-card-form').onsubmit=async e=>{e.preventDefault();const body=$('#edit-card-body').value;if(i.kind==='link'&&safeUrl(body)==='#'){toast('Use a valid http or https URL.',true);return}try{await mutate(async()=>{const r=await api('/items/'+id,{method:'PATCH',body:{version:i.version,body}});i.body=body;i.version=r.version});closeModal();renderCanvas()}catch{}}}
// Idle refresh never replaces a draft, drag, dialog, or focused form field.
setInterval(async()=>{if(!state.me||state.screen!=='session'||state.busy||dirty||drag||uploading||$('.modal')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{const fresh=await api('/sessions/'+state.session.id);const signature=s=>JSON.stringify([s.version,s.items.map(i=>[i.id,i.version,i.likes,i.comments]),s.notes]);if(signature(fresh)!==signature(state.session)){state.session=fresh;render();toast('The session has been updated.')}}catch(e){if(e.status===410){state.me=null;login(e.message)}}},12000);

function ownerSetup(){const token=new URLSearchParams(location.search).get('setup');$('#preview-entry')?.remove();$('#app').innerHTML=`<div class="login"><div class="login-visual"><div class="login-quote">Your ideas.<br>Your own space.</div></div><div class="login-content"><form class="login-form" id="owner-setup-form"><a class="brand" href="/">${brand()}</a><div class="eyebrow">Your private Shoots workspace</div><h1 style="margin-top:13px">Make it yours, Mario.</h1><p>Choose your workspace password. This setup link can only be used once.</p><div class="field"><label for="setup-password">Choose a password</label><input id="setup-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required placeholder="At least 12 characters"></div><div class="field" style="margin-top:18px"><label for="setup-confirm">Confirm password</label><input id="setup-confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></div><div class="error" id="setup-error"></div>${btn('lock','Open my workspace','btn primary','type="submit"')}</form></div></div>`;$('#owner-setup-form').onsubmit=async e=>{e.preventDefault();const a=$('#setup-password').value,b=$('#setup-confirm').value;if(a!==b){$('#setup-error').textContent='The passwords do not match.';return}const button=$('button[type=submit]',e.target);button.disabled=true;try{await api('/setup',{method:'POST',body:{token,password:a}});await api('/login',{method:'POST',body:{password:a}});history.replaceState(null,'',location.pathname);await boot();toast('Your private workspace is ready.')}catch(err){$('#setup-error').textContent=err.message;button.disabled=false}}}
function referenceRatio(i){return croppedRatio(i.ratio||.75,i.transform?.crop)}
function photoHTML(i,options={}){
 const id=options.library?i.id:i.asset,t=i.transform||{},c=normalizeCrop(t.crop),ratio=i.ratio||.75;
 const effect=options.canvas?`filter:grayscale(${t.gray||0}) brightness(${t.brightness||1});border-radius:${t.radius||0}px;`:'';
 if(c){const style=options.canvas||options.viewer?'width:100%;height:100%;':`display:block;width:100%;height:auto;aspect-ratio:${referenceRatio(i)};`;return `<svg class="cropped-photo" role="img" aria-label="${esc(i.name)}" xmlns="http://www.w3.org/2000/svg" viewBox="${c.x*ratio} ${c.y} ${c.w*ratio} ${c.h}" preserveAspectRatio="xMidYMid ${options.canvas&&t.fit==='cover'?'slice':'meet'}" style="${style}${effect}" ${options.canvas?'pointer-events="none"':''}><title>${esc(i.name)}</title><image href="${media(id)}" width="${ratio}" height="1" preserveAspectRatio="none"/></svg>`}
 return `<img src="${media(id,!!options.thumb)}" ${!options.viewer&&!options.canvas?`srcset="${media(id,true)} 600w, ${media(id)} 1600w" sizes="(max-width:767px) 46vw, 28vw"`:''} alt="${esc(i.name)}" loading="${options.loading||'eager'}" draggable="false" width="600" height="${Math.round(600/ratio)}" ${options.canvas?`style="object-fit:${t.fit||'contain'};${effect}"`:''}>`;
}
function deleteSession(){
 const session=state.session,name=session.details.name;
 modal(`${modalHead('Delete this session?')}<p>This permanently removes <strong>${esc(name)}</strong>, including its board, notes, comments, favorites, and sharing links.</p><p style="margin-top:12px">Uploaded photographs stay in your private inspiration library and any other sessions that use them.</p><form id="delete-session-form"><div class="field"><label for="delete-session-name">Type DELETE to confirm</label><input id="delete-session-name" autocomplete="off" required placeholder="DELETE"></div><div class="error" id="delete-error"></div><div class="modal-actions">${btn('','Keep session','btn ghost','type="button" data-close')}${btn('trash','Delete permanently','btn danger','type="submit" id="delete-submit" disabled')}</div></form>`);
 const input=$('#delete-session-name'),submit=$('#delete-submit');input.oninput=()=>{submit.disabled=input.value.trim().toUpperCase()!=='DELETE'};
 $('#delete-session-form').onsubmit=async e=>{e.preventDefault();if(input.value.trim().toUpperCase()!=='DELETE')return;submit.disabled=true;try{await mutate(()=>api('/sessions/'+session.id,{method:'DELETE',body:{version:session.version,confirmation:input.value}}));closeModal();await navigate('sessions');toast('Session deleted. Its photographs remain in your library.')}catch(err){$('#delete-error').textContent=err.message;submit.disabled=false}};
}
function cropEditor(id){
 const i=findItem(id);if(!i?.asset||!edit())return;const initial=normalizeCrop(i.transform.crop)||{x:0,y:0,w:1,h:1};let rect={...initial},gesture=null,drawNew=false;
 modal(`${modalHead('Keep just the part you need.')}<p>Drag a new selection, move the box, or resize its corners. The original photograph stays intact.</p><div class="crop-stage" id="crop-stage" style="--source-ratio:${i.ratio||.75};width:min(100%,calc(53svh * ${i.ratio||.75}));aspect-ratio:${i.ratio||.75}"><img src="${media(i.asset)}" alt="Original reference for cropping" draggable="false"><div class="crop-selection" id="crop-selection" tabindex="0" role="group" aria-label="Crop selection. Use arrow keys to move it.">${['nw','ne','sw','se'].map(v=>`<span class="crop-corner ${v}" data-crop-corner="${v}"></span>`).join('')}<span class="crop-thirds vertical one"></span><span class="crop-thirds vertical two"></span><span class="crop-thirds horizontal one"></span><span class="crop-thirds horizontal two"></span></div></div><form id="crop-form"><div class="crop-fields">${[['x','Left'],['y','Top'],['w','Width'],['h','Height']].map(([key,label])=>`<div class="field"><label for="crop-${key}">${label} %</label><input id="crop-${key}" type="number" step=".1" min="${key==='w'||key==='h'?1:0}" max="100" data-crop-field="${key}"></div>`).join('')}</div><div class="error" id="crop-error"></div><div class="modal-actions between"><div class="row">${btn('fit','New selection','btn ghost','type="button" id="crop-new"')}${btn('undo','Reset crop','btn ghost','type="button" id="crop-reset"')}</div><div class="row">${btn('','Cancel','btn ghost','type="button" data-close')}${btn('check','Apply crop','btn primary','type="submit" id="crop-apply"')}</div></div></form>`,'crop-modal');
 const stage=$('#crop-stage'),selection=$('#crop-selection');
 const paint=()=>{selection.style.left=rect.x*100+'%';selection.style.top=rect.y*100+'%';selection.style.width=rect.w*100+'%';selection.style.height=rect.h*100+'%';$$('[data-crop-field]').forEach(input=>{if(document.activeElement!==input)input.value=(rect[input.dataset.cropField]*100).toFixed(1)})};
 const constrain=()=>{rect=normalizeCrop(rect)||{x:0,y:0,w:1,h:1};paint()};
 const point=e=>{const b=stage.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}};
 stage.onpointerdown=e=>{if(e.button&&e.button!==0)return;e.preventDefault();const p=point(e),corner=e.target.closest('[data-crop-corner]')?.dataset.cropCorner;const inside=!drawNew&&selection.contains(e.target);gesture={start:p,before:{...rect},mode:drawNew?'draw':corner||(inside?'move':'draw')};drawNew=false;$('#crop-new').classList.remove('primary');stage.setPointerCapture(e.pointerId);if(gesture.mode==='draw'){rect={x:p.x,y:p.y,w:.01,h:.01};paint()}};
 stage.onpointermove=e=>{if(!gesture)return;const p=point(e),b=gesture.before,dx=p.x-gesture.start.x,dy=p.y-gesture.start.y,m=gesture.mode;if(m==='move'){rect={...b,x:Math.max(0,Math.min(1-b.w,b.x+dx)),y:Math.max(0,Math.min(1-b.h,b.y+dy))}}else if(m==='draw'){const x=Math.min(gesture.start.x,p.x),y=Math.min(gesture.start.y,p.y);rect={x,y,w:Math.max(.01,Math.abs(p.x-gesture.start.x)),h:Math.max(.01,Math.abs(p.y-gesture.start.y))}}else{let left=b.x,right=b.x+b.w,top=b.y,bottom=b.y+b.h;if(m.includes('w'))left=Math.max(0,Math.min(right-.01,b.x+dx));if(m.includes('e'))right=Math.min(1,Math.max(left+.01,b.x+b.w+dx));if(m.includes('n'))top=Math.max(0,Math.min(bottom-.01,b.y+dy));if(m.includes('s'))bottom=Math.min(1,Math.max(top+.01,b.y+b.h+dy));rect={x:left,y:top,w:right-left,h:bottom-top}}constrain()};
 stage.onpointerup=()=>{gesture=null;constrain()};stage.onpointercancel=()=>{if(gesture){rect=gesture.before;gesture=null;paint()}};
 selection.onkeydown=e=>{const delta=e.shiftKey ? .02 : .002;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();rect.x=Math.max(0,Math.min(1-rect.w,rect.x+(e.key==='ArrowLeft'?-delta:e.key==='ArrowRight'?delta:0)));rect.y=Math.max(0,Math.min(1-rect.h,rect.y+(e.key==='ArrowUp'?-delta:e.key==='ArrowDown'?delta:0)));paint()};
 $$('[data-crop-field]').forEach(input=>input.oninput=()=>{rect[input.dataset.cropField]=Number(input.value)/100;constrain()});$('#crop-new').onclick=()=>{drawNew=true;$('#crop-new').classList.add('primary')};$('#crop-reset').onclick=()=>{rect={x:0,y:0,w:1,h:1};paint()};
 $('#crop-form').onsubmit=async e=>{e.preventDefault();const button=$('#crop-apply');button.disabled=true;const crop=normalizeCrop(rect),next={...i.transform,crop,fit:'contain',h:Math.min(2000,Math.max(60,i.transform.w/croppedRatio(i.ratio||.75,crop)))};try{await mutate(async()=>{const r=await api('/items/'+id,{method:'PATCH',body:{version:i.version,transform:next}});undoStack.push([{id:i.id,before:structuredClone(i.transform),after:structuredClone(next)}]);redoStack=[];i.transform=next;i.version=r.version});closeModal();render();viewer(id);toast(crop?'Crop saved across your session views.':'Original framing restored.')}catch(err){$('#crop-error').textContent=err.message;button.disabled=false}};
 paint();
}
let loginMode=location.pathname==='/admin'?'admin':'client';
function login(message=''){
 if(guestToken){legacyLogin(message);return;}
 ro?.disconnect();$('#app').innerHTML=`<div class="login"><div class="login-visual"><div class="login-quote">Good photographs<br>begin with an idea.</div></div><div class="login-content"><form class="login-form" id="client-login"><a class="brand" href="/">${brand()}</a><div class="segmented" style="margin:25px 0"><button type="button" data-login-mode="client" class="${loginMode==='client'?'active':''}">Client login</button><button type="button" data-login-mode="admin" class="${loginMode==='admin'?'active':''}">Admin login</button></div><h1>${loginMode==='admin'?'Welcome back, Mario.':'Your next shoot starts here.'}</h1><p>${loginMode==='admin'?'Open your photography workspace.':'Sign in to find your shoots, inspiration and plans.'}</p>${loginMode==='client'?'<div class="field"><label for="client-email">Email address</label><input id="client-email" name="email" type="email" autocomplete="username" required></div>':''}<div class="field" style="margin-top:18px"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div>${loginMode==='client'?'<label class="row tiny" style="margin-top:18px"><input type="checkbox" name="remember"> Remember this device for 30 days</label>':''}<div id="login-error" class="error" role="alert">${esc(message)}</div>${btn('arrow','Sign in','btn primary','type="submit"')}<p class="tiny muted" style="margin-top:20px">${loginMode==='client'?'Forgot your password? Ask Mario to reset it.':'Private photography workspace'}</p></form></div></div>`;
 $$('[data-login-mode]').forEach(b=>b.onclick=()=>{loginMode=b.dataset.loginMode;login()});$('#client-login').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.remember=!!d.remember;await api(loginMode==='client'?'/client-login':'/login',{method:'POST',body:d});await boot()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}};
}
function clientFields(){return `<div class="field"><label for="client-name">Name</label><input id="client-name" name="name" autocomplete="name" required maxlength="60"></div><div class="field"><label for="new-client-email">Email address</label><input id="new-client-email" name="email" type="email" autocomplete="off" required></div><div class="field"><label for="initial-password">Initial password</label><input id="initial-password" name="password" type="password" autocomplete="new-password" required minlength="4" maxlength="128"><small>Their phone number is fine. They can change it after signing in.</small></div>`}
async function manageClients(){try{const clients=await api('/clients');modal(`${modalHead('Clients')}<p>Create a client login, then assign their shoots through Invite.</p><form id="add-client" class="client-fields">${clientFields()}<div class="modal-actions">${btn('plus','Add client','btn primary','type="submit"')}</div></form><hr>${clients.map(c=>`<div class="client-row"><div><strong>${esc(c.name)}</strong><p class="tiny">${esc(c.email)}${c.active?'':' · Access disabled'}</p></div><div class="row wrap">${btn('lock','Reset password','btn',`data-reset-client="${c.id}"`)}${btn('','Remove client','btn danger',`data-delete-client="${c.id}"`)}</div></div>`).join('')}`);$('#add-client').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{await api('/clients',{method:'POST',body:Object.fromEntries(new FormData(e.target))});toast('Client added. Assign their shoots through Invite.');await manageClients()}catch(err){toast(err.message,true);b.disabled=false}};$$('[data-reset-client]').forEach(b=>b.onclick=()=>resetClientPassword(b.dataset.resetClient));$$('[data-delete-client]').forEach(b=>b.onclick=()=>confirmModal('Remove this client?','Their login and all shoot access will be removed. Their contributions stay on the shoots.',async()=>{await api('/clients/'+b.dataset.deleteClient,{method:'DELETE',body:{}});toast('Client access removed.')}));}catch(e){toast(e.message,true)}}
function resetClientPassword(id){modal(`${modalHead('Reset client password')}<form id="reset-client"><div class="field"><label for="reset-password">New password</label><input id="reset-password" name="password" type="password" autocomplete="new-password" required minlength="4" maxlength="128"></div><p>Share the new password with the client. Existing sign-ins will end.</p><div class="modal-actions">${btn('check','Reset password','btn primary','type="submit"')}</div></form>`);$('#reset-client').onsubmit=async e=>{e.preventDefault();try{await api('/clients/'+id,{method:'PATCH',body:Object.fromEntries(new FormData(e.target))});closeModal();toast('Password reset.')}catch(err){toast(err.message,true)}}}
function changeClientPassword(){modal(`${modalHead('Change password')}<form id="change-password"><div class="field"><label for="current-password">Current password</label><input id="current-password" name="current" type="password" autocomplete="current-password" required></div><div class="field"><label for="new-password">New password</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="4" maxlength="128" required></div><div class="field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password" required></div><div class="modal-actions">${btn('check','Save password','btn primary','type="submit"')}</div></form>`);$('#change-password').onsubmit=async e=>{e.preventDefault();if($('#new-password').value!==$('#confirm-password').value){toast('The passwords do not match.',true);return;}try{await api('/account/password',{method:'POST',body:Object.fromEntries(new FormData(e.target))});closeModal();toast('Password changed.')}catch(err){toast(err.message,true)}}}
async function shootAccess(){try{const sid=state.session.id,[clients,assigned]=await Promise.all([api('/clients'),api('/sessions/'+sid+'/clients')]);modal(`${modalHead('Share this shoot')}<form id="shoot-address"><div class="field"><label for="short-address">Short address</label><div class="tiny muted">${esc(location.origin)}/</div><input id="short-address" name="slug" value="${esc(state.session.slug||state.session.details.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60))}" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="60" required></div><div class="row wrap">${btn('check','Save address','btn','type="submit"')}${state.session.slug?btn('copy','Copy address','btn','type="button" id="copy-shoot-address"'):''}</div></form><p class="tiny">Clients must sign in and have access to this shoot. Knowing its address does not grant access.</p><hr><h3>Client access</h3>${clients.length?`<form id="assign-client"><div class="field"><label for="assign-client-id">Client</label><select id="assign-client-id" name="client">${clients.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.email)}</option>`).join('')}</select></div><div class="field"><label for="assign-role">Permissions</label><select id="assign-role" name="role"><option value="contribute">Contribute · upload, comment and shared notes</option><option value="view">View only</option><option value="collaborate">Collaborate · also arrange the canvas</option></select></div>${btn('plus','Assign shoot','btn primary','type="submit"')}</form>`:'<p>Add a client first, then assign this shoot.</p>'}<div class="row wrap" style="margin-top:15px">${btn('plus','Manage clients','btn','id="manage-clients"')}${btn('link','Guest invitations','btn ghost','id="legacy-sharing"')}</div>${assigned.map(c=>`<div class="client-row"><div><strong>${esc(c.name)}</strong><p class="tiny">${esc(c.email)} · ${esc(roleText(c.role))}</p></div>${btn('close','Remove access','btn',`data-unassign="${c.id}"`)}</div>`).join('')}`);$('#manage-clients').onclick=manageClients;$('#legacy-sharing').onclick=sharing;$('#shoot-address').onsubmit=async e=>{e.preventDefault();try{const r=await api('/sessions/'+sid+'/address',{method:'PUT',body:Object.fromEntries(new FormData(e.target))});state.session.slug=r.slug;history.replaceState(null,'','/'+r.slug);toast('Short address saved.');await shootAccess()}catch(err){toast(err.message,true)}};if($('#copy-shoot-address'))$('#copy-shoot-address').onclick=()=>copyText(location.origin+'/'+state.session.slug);if($('#assign-client'))$('#assign-client').onsubmit=async e=>{e.preventDefault();try{await api('/sessions/'+sid+'/clients',{method:'PUT',body:Object.fromEntries(new FormData(e.target))});toast('Shoot assigned.');await shootAccess()}catch(err){toast(err.message,true)}};$$('[data-unassign]').forEach(b=>b.onclick=()=>confirmModal('Remove shoot access?','This client will lose access to this shoot immediately.',async()=>{await api('/sessions/'+sid+'/clients',{method:'DELETE',body:{client:b.dataset.unassign}});toast('Shoot access removed.')}));}catch(e){toast(e.message,true)}}
